import{_ as a,H as t,f as s,i}from"./chunks/framework.BH2BK_3i.js";const H=JSON.parse('{"title":"08 | HBase如何组织与存储数据？","description":"","frontmatter":{},"headers":[{"level":2,"title":"HBase 数据组织的逻辑模型","slug":"hbase-数据组织的逻辑模型","link":"#hbase-数据组织的逻辑模型","children":[]},{"level":2,"title":"分区，弹性伸缩的基本单元","slug":"分区-弹性伸缩的基本单元","link":"#分区-弹性伸缩的基本单元","children":[]},{"level":2,"title":"HBase 数据存储的物理模型","slug":"hbase-数据存储的物理模型","link":"#hbase-数据存储的物理模型","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"分布式数据库从入门到实战/08｜HBase如何组织与存储数据？.md","filePath":"分布式数据库从入门到实战/08｜HBase如何组织与存储数据？.md","lastUpdated":1795541719000}'),p={name:"分布式数据库从入门到实战/08｜HBase如何组织与存储数据？.md"};function r(o,e,l,E,n,B){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="_08-hbase如何组织与存储数据" tabindex="-1">08 | HBase如何组织与存储数据？ <a class="header-anchor" href="#_08-hbase如何组织与存储数据" aria-label="Permalink to &quot;08 | HBase如何组织与存储数据？&quot;">​</a></h1><p>你好，我是彭旭。</p><p>上节课，我们分析了云服务的数据存储需求，了解了之前基于 MySQL 的分库分表支撑海量数据的存储与读写的过程。但是，因为硬件与运维上的巨大成本，我们不得不谋求一个新的存储方案。</p><p>这两节课，我们就一起学习 HBase 的架构和原理，看看 HBase 是怎么解决之前的问题的。</p><p>今天我们会聚焦在 HBase 组织数据的方式上，解决上节课提到的运维成本问题。希望通过这节课的学习，你能了解两个关键知识点。</p><ol><li><p>HBase 如何存储数据，给数据分区。在集群扩容的过程中，HBase 自动迁移分区从而实现负载均衡的过程。</p></li><li><p>HBase 物理上存储数据的方法，HBase 集群包含的组件以及组件之间的协作方式。</p></li></ol><h2 id="hbase-数据组织的逻辑模型" tabindex="-1">HBase 数据组织的逻辑模型 <a class="header-anchor" href="#hbase-数据组织的逻辑模型" aria-label="Permalink to &quot;HBase 数据组织的逻辑模型&quot;">​</a></h2><p>使用一个数据库，第一步可以去理解它的数据模型，还有它的数据是怎么组织的。</p><p>HBase 和关系型数据库一样，以数据表的形式组织数据。一张表包含多行数据，每行数据都由一个唯一的行键来标识。</p><p>数据在表中以行键的字典序排序，像这张图一样。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%93%E4%BB%8E%E5%85%A5%E9%97%A8%E5%88%B0%E5%AE%9E%E6%88%98/images/08/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%93%E4%BB%8E%E5%85%A5%E9%97%A8%E5%88%B0%E5%AE%9E%E6%88%98/images/08/1.png" alt=""></a></p><ol><li><p>行键类似关系型数据库主键，通过行键可以定位到一行数据。对 HBase 来说，通过行键来读取单行或者多行数据最高效。当然，它也支持基于行键区间的扫描。</p></li><li><p>HBase 是一个宽列族存储数据库，数据按列族聚簇存储在一起。虽然 HBase 是列式存储数据库，但不建议一个表有多个列族。所以，在单个列族的情况下，基本上就跟行式存储类似了。</p></li><li><p>HBase 建表的时候需要至少指定一个列族，但是不需要声明列。每一行数据都可以定义属于自己的列，也就是支持动态的 Schema。但是每行的列不一定有值，所以 HBase 是一个稀疏表。</p></li></ol><p>看到这里你应该还记得上一节课我们讲到的需要兼容多版本的客户端。之前 MySQL 场景下增减字段都需要走大表 DDL 的需求，而这种动态 Schema 的设计，就很好地解决了这个问题。</p><ol start="4"><li>每一列其实都是一个 KeyValue 键值对，但是可以有多个版本。每个版本会有一个时间戳，你可以在建表的时候指定需要保留最近的 N 个版本。</li></ol><p>HBase 的数据模型非常灵活，你可以按需为每行数据定义不同的字段，即使定义了较多的列，只要列没有实际存储数据，就不会占用存储空间。</p><p>HBase 不提供多表关联查询的能力，所以比较适合单表存储能搞定的业务，比如云服务场景下，通话记录、联系人、短信等都可以用一张表来解决，就很适合用 HBase 存储。</p><p>总结一下，HBase 的逻辑模型其实类似一个嵌套了多层的 Map，你可以根据行键、列族、列限定符、数据版本一层层递进，找到存储的行、列的数据。</p><h2 id="分区-弹性伸缩的基本单元" tabindex="-1">分区，弹性伸缩的基本单元 <a class="header-anchor" href="#分区-弹性伸缩的基本单元" aria-label="Permalink to &quot;分区，弹性伸缩的基本单元&quot;">​</a></h2><p>数据行分片后就形成了分区，那么一个分区自然也就包含多行数据。那 HBase 是怎么管理分区的呢？</p><p>在基础篇里面我们讲到 HBase 是基于行键，按区间分区的。</p><p>事实上，默认情况下，你甚至都不需要关注 HBase 是如何分区的，当分区文件达到配置的大小后，HBase 会自动将大分区从中间分裂成两个小的分区。</p><p>如果某个区间段的分区数据被删除了很多，HBase 又会自动把相邻的小分区合并成大一点的分区。因为分区太多对集群的管理来说也是负担。</p><p>HBase 数据分布像下面这张图一样，每个分区大小很均匀，而且是均衡地分布在集群的各个节点上。这里需要注意的是，如果集群节点做了扩容，HBase 可能需要一定的时间来将分区进行 relocate 以及本地化，达到最佳性能。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%93%E4%BB%8E%E5%85%A5%E9%97%A8%E5%88%B0%E5%AE%9E%E6%88%98/images/08/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%93%E4%BB%8E%E5%85%A5%E9%97%A8%E5%88%B0%E5%AE%9E%E6%88%98/images/08/2.png" alt=""></a></p><p>总结一下，分区是 HBase 中数据分布与负载均衡的最小单元，HBase 能够自动帮我们拆分、合并这些分区。当数据量增长到当前机器配置无法支撑的情况时，我们只需要在集群中增加一些服务器节点，HBase 就可以自动帮我们迁移分区、平衡数据与请求。</p><p>还是回到在云服务的场景中，联系人、通话记录等都很适合用用户 ID 做分区，而且你会发现，之前需要手动分库分表的情况在 HBase 场景下完全自动化了，这样就再也不用凌晨停机去做数据迁移了。</p><h2 id="hbase-数据存储的物理模型" tabindex="-1">HBase 数据存储的物理模型 <a class="header-anchor" href="#hbase-数据存储的物理模型" aria-label="Permalink to &quot;HBase 数据存储的物理模型&quot;">​</a></h2><p>那 HBase 是如何存储这些分区的呢？再来看看 HBase 数据存储的物理模型。</p><p>先来看一张 HBase 集群的架构图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%93%E4%BB%8E%E5%85%A5%E9%97%A8%E5%88%B0%E5%AE%9E%E6%88%98/images/08/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%93%E4%BB%8E%E5%85%A5%E9%97%A8%E5%88%B0%E5%AE%9E%E6%88%98/images/08/3.png" alt=""></a></p><p>可以看到，这里涉及 3 个物理组件。Master 对应进程 HMaster，RegionServer 对应进程HRegionServer 以及 Zookeeper，以及存储上 HBase 所依赖的 Hadoop DFS 组件。</p><p>首先来看一下集群中最繁忙，也是物理上的弹性伸缩单元 RegionServer。它的工作最明确，就是给客户端提供数据的读写服务。一个 RegionServer 通常可以负责成百上千个分区，这些分区的读写请求就由它来提供服务。</p><p>反过来，一个分区同时只会由一个 RegionServer 提供服务，而不像某些存储引擎（比如StarRocks、Kudu）一个分区可以由多个节点提供服务，其中一个作为主节点提供数据读写能力，其他节点作为从节点提供数据读取能力。</p><p>再来看一下集群的“管家” Master。你可以看到，图中有 active 和 standBy 两个 HMaster 进程，实际上，一个 HBase 集群可以有多个 Master 来竞争成为 active 的 Master。只要 active的 Master 宕机了，或者在 Zookeeper 上的租期过期了，其他 standBy 的 Master 就会竞争成为新的 active Master，实现高可用，确保集群正常运行。</p><p>Master 实际上主要负责这么几个工作。</p><ol><li><p>监控 RegionServer 的状态。在 RegionServer 故障时，将故障 RegionServer 的分区重新分配给其他活跃的 RegionServer。</p></li><li><p>分配管理分区。将分区在集群内均衡地分配给 RegionServer。</p></li><li><p>涉及集群管理的操作，如管理表与列族的变更、分区的 Split 合并等都由 Master 负责。</p></li></ol><p>你可以参考 HMaster.java 类的方法来看看 Master 实际上负责了哪些事情。</p><p>事实上，Master 和 RegionServer 已经提供了 HBase 作为一个数据库需要的所有服务。但是，和所有分布式系统一样，它还需要一个分布式协调服务来提供配置管理、Master 选举、元数据存储等功能。而 Zookeeper 作为 Hadoop 生态里备受青睐的分布式协调服务，被HBase 选用就顺理成章了。</p><p>Zookeeper 在 HBase 集群中主要用来做分布式协调。举几个例子吧。</p><ul><li><p>确保同时只有一个 active 的 Master。</p></li><li><p>集群一些元数据的存储，比如活跃的 RegionServer、分区 Split 过程中的一些数据等，实际上集群节点的故障检测与恢复，都依赖这些元数据来实现。</p></li><li><p>存储客户端会引导数据 hbase:meta 表所在的 RegionServer。这个 hbase:meta 元数据表是用来让客户端搞清楚操作的数据分布在哪个分区，应该与哪个 RegionServer 打交道。在下节课会详细介绍。</p></li></ul><p>从物理进程上来说，这 3 个组件组成了整个集群。RegionServer 的工作最为直接，但是也是最为复杂的一个组件。我们再来细看一下 RegionServer 内部有哪些组件。</p><p>第一个是 WAL（Write-Ahead-Log，预写式日志），这个我们在第 2 节课介绍 LSM 的时候有说到，这里复习一下。</p><p>WAL 类似关系型数据库的 Redo 日志，数据写入 MemStore 之前，会将对数据的操作（如Put、Delete 等操作）记录到 WAL 预写入日志文件。这个文件是以追加的形式批量顺序写入磁盘的，所以速度很快。当程序崩溃导致内存 MemStore 数据丢失后，HBase RegionServer会重放这个 WAL 日志文件中的数据操作，在内存中重建 MemStore 的数据。</p><p>为了提升并发，每个分区 Region 会有一个 WAL。所以，不同的分区可以并发地写入自己的WAL，以免写入磁盘竞争太大，这对性能也是一个提升。</p><p>第二个是 Store 存储仓库，每个列族对应一个存储仓库，一个存储仓库包含一个 MemStore和多个存储文件。当 MemStore 的大小达到了配置的阈值后，会作为一个文件刷新、输出、存储到磁盘里。这个存储文件按顺序写入磁盘，不支持修改，以 HFile 的形式存储在 Hadoop 的DataNode 中。</p><p>这个存储仓库又可以细分为 MemStore 和 StoreFile。</p><p>MemStore 位于分区服务器的堆内存，它是一个基于 NavigableSet 存储的有序数据结构。数据在写入 MemStore 的时候就会按行键排序，刷新输出到存储文件 StoreFile 的时候会按顺序遍历写入，提高写性能。同时，根据局部性原理，新插入数据总是比老数据使用频繁。所以，MemStore 新写入数据的访问速度也是不低的。</p><p>另一个 StoreFile 由数据块 Block 组成，而数据块就是 HBase 数据读取的最小单元，你可以在建表时按列族指定表的数据块大小。如果表启用了前面提到的数据压缩，那么数据在写入StoreFile 之前就会按数据块进行压缩，读取时，也同样是对数据块解压后再放入缓存。</p><p>这里提一下，理想情况下，每次读取数据的大小都是指定的数据块大小的倍数，这样可以避免一些无效的 I/O，效率最高。所以，如果你的程序里面针对较少行的随机读取较多，就可以设置小一点的数据块。反过来，如果按顺序的扫描较多，则可以设置大一点的数据块。</p><p>最后我用一棵树来结合整理一下 HBase 逻辑上的表、分区和物理上存储模型的关系。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%93%E4%BB%8E%E5%85%A5%E9%97%A8%E5%88%B0%E5%AE%9E%E6%88%98/images/08/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%93%E4%BB%8E%E5%85%A5%E9%97%A8%E5%88%B0%E5%AE%9E%E6%88%98/images/08/4.png" alt=""></a></p><p>再强调一点，HBase 本身并不提供存储功能，而是基于 HDFS 存储。StoreFile 在 HDFS 中对应 HFile，WAL 生成的日志对应 HLog。因为是基于 HDFS 存储数据，因此在进行分区迁移时，无需真正移动数据。然而，换个角度看，这也意味着 HBase 与 HDFS 紧密耦合，无法实现存储与计算的分离，节省成本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>好了，到这里你应该对 HBase 的逻辑模型跟物理模型都有了一个了解。</p><p>HBase 的逻辑模型其实跟关系型数据库类似，但是 HBase 会保存多个版本的数据，默认情况下会读取数据的最新版本，你也可以指定版本或者时间区间来读取一个历史的数据版本。</p><p>分区类似关系型数据库的分库分表，但是在 HBase 中实现了分区的自动管理与负载均衡，这样在增加服务器节点时，再也不需要做数据迁移了。</p><p>HBase 集群物理上由 3 个组件组成，负责提供读写服务的 RegionServer，负责分区管理与调度的 Master 以及负责分布式协调的 Zookeeper。</p><p>此外，HBase 依赖于 Hadoop HDFS 作为数据存储，这也是 HBase 被人诟病的一个瓶颈。因为它使得 HBase 与 HDFS 紧密耦合，无法实现存算分离的架构，增加了系统的复杂性和维护成本。</p><p>最后给你一个建议，虽然 HBase 能够自动管理分区，自动拆分与合并并且负载均衡，但是我还是建议你在定义表的时候就想清楚数据该如何分布，为数据表预先定义好分区。这样可以避免业务高峰期分区的自动拆分与合并引起系统负载过高，导致服务响应时长变长，甚至引起雪崩。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在逻辑模型中提到，一个 HBase 表不建议有多个列族，你知道这是为什么吗？</p><p>欢迎你在留言区和我交流。如果觉得有所收获，也可以把课程分享给更多的朋友一起学习。欢迎你加入我们的读者交流群，我们下节课见！</p>',62)])])}const g=a(p,[["render",r]]);export{H as __pageData,g as default};
